/** التنبيهات — general and personal tabs, read states, bulk actions.
 *  Every notification shown here was generated by a real backend event. */

import { useCallback, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { BottomNav, ScreenHeader } from '../components/AppShell';
import { Icon } from '../components/Icons';
import {
  Button, Card, ConfirmDialog, EmptyState, ErrorState, ListSkeleton, Segmented, Toast,
} from '../components/ui';
import { api } from '../lib/api';
import { arDate } from '../lib/format';
import { useApi } from '../lib/useApi';
import type { NotificationItem } from '../lib/types';

const KIND_ICON: Record<string, 'check' | 'alert' | 'clock' | 'calendar' | 'info' | 'glucose'> = {
  report_ready: 'check',
  report_failed: 'alert',
  followup_submitted: 'clock',
  followup_decided: 'glucose',
  appointment_created: 'calendar',
  general: 'info',
};

function NotificationCard({ item, onOpen }: { item: NotificationItem; onOpen: () => void }) {
  const [expanded, setExpanded] = useState(false);
  const long = item.body_ar.length > 110;
  return (
    <Card as="article" className="sp-notification overflow-hidden">
      <div className="p-4">
        <div className="flex items-start gap-3">
          <span className="relative grid place-items-center size-10 shrink-0 rounded-xl
            bg-primary-soft text-primary">
            <Icon name={KIND_ICON[item.kind] ?? 'info'} size={19} />
            {!item.read && (
              <span className="absolute -top-1 -left-1 size-2.5 rounded-full bg-unread"
                aria-label="غير مقروء" />
            )}
          </span>
          <div className="min-w-0 flex-1">
            <div className="flex items-baseline justify-between gap-3">
              <p className="text-[12.5px] text-ink-2 truncate">{item.sender_ar}</p>
              <p className="sp-ltr shrink-0 text-[12px] text-ink-3">{arDate(item.created_at)}</p>
            </div>
            <h3 className="mt-0.5 text-[14.5px] font-bold text-primary">{item.title_ar}</h3>
            <p className={`mt-1 text-[13px] leading-relaxed text-ink-2 ${expanded || !long ? '' : 'line-clamp-2'}`}>
              {item.body_ar}
            </p>
            {long && (
              <button type="button" onClick={() => setExpanded((v) => !v)}
                className="mt-1 text-[12.5px] font-medium text-primary">
                {expanded ? 'عرض أقل' : 'اقرأ المزيد...'}
              </button>
            )}
          </div>
        </div>
      </div>
      <button
        type="button"
        onClick={onOpen}
        className="sp-pressable w-full border-t border-line/70 py-2.5 text-center
          text-[13px] font-medium text-primary"
      >
        عرض التفاصيل
      </button>
    </Card>
  );
}

export default function NotificationsScreen() {
  const navigate = useNavigate();
  const [tab, setTab] = useState<'personal' | 'general'>('personal');
  const { data, error, loading, reload } = useApi(() => api.notifications());
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [busy, setBusy] = useState(false);
  const [toast, setToast] = useState<string | null>(null);

  const items = (data?.items ?? []).filter((n) => n.channel === tab);

  const open = useCallback(async (item: NotificationItem) => {
    if (!item.read) {
      try { await api.readNotification(item.id); } catch { /* non-blocking */ }
    }
    if (item.link) navigate(item.link);
    else navigate(`/notifications/${item.id}`);
  }, [navigate]);

  async function markAll() {
    setBusy(true);
    try {
      const r = await api.readAllNotifications();
      setToast(`تم تعليم ${r.count} تنبيهًا كمقروء.`);
      reload();
    } catch {
      setToast('تعذّر تنفيذ العملية.');
    } finally {
      setBusy(false);
    }
  }

  async function deleteAll() {
    setBusy(true);
    try {
      await api.deleteNotifications(tab);
      setConfirmDelete(false);
      setToast('تم حذف التنبيهات.');
      reload();
    } catch {
      setToast('تعذّر الحذف.');
    } finally {
      setBusy(false);
    }
  }

  return (
    <>
      <ScreenHeader
        title="التنبيهات"
        back
        action={
          <button type="button" onClick={() => setConfirmDelete(true)}
            className="sp-pressable rounded-xl px-2 py-1.5 text-[13px] font-medium text-primary">
            حذف الكل
          </button>
        }
      />
      <main className="sp-notifications sp-scroll px-4 pt-4">
        <Segmented
          value={tab}
          onChange={setTab}
          options={[
            { value: 'personal', label: 'الخاصة', badge: data?.personal_count },
            { value: 'general', label: 'العامة', badge: data?.general_count },
          ]}
        />

        {data && data.unread_total > 0 && (
          <div className="mt-3 flex justify-start">
            <Button variant="ghost" onClick={() => void markAll()} loading={busy}
              className="!min-h-0 !px-3 !py-1.5 !text-[13px]">
              تعليم الكل كمقروء
            </Button>
          </div>
        )}

        <div className="mt-4 space-y-3">
          {loading && <ListSkeleton rows={3} />}
          {error && <ErrorState message={error.messageAr} onRetry={reload} />}
          {data && items.length === 0 && (
            <EmptyState
              icon="info"
              title={tab === 'personal' ? 'لا توجد تنبيهات خاصة' : 'لا توجد تنبيهات عامة'}
              body={tab === 'personal'
                ? 'ستظهر هنا تنبيهات تقاريرك وطلبات المتابعة ومواعيدك التجريبية.'
                : 'تنبيهات عامة عن الخدمة وطريقة استخدامها.'}
            />
          )}
          {items.map((item) => (
            <NotificationCard key={item.id} item={item} onOpen={() => void open(item)} />
          ))}
        </div>

        <p className="mt-6 px-2 text-center text-[11.5px] text-ink-3">
          تُنشأ التنبيهات من أحداث فعلية في الخادم فقط، ولا تتكرر عند إعادة تحميل الصفحة.
        </p>
      </main>

      <BottomNav />
      <ConfirmDialog
        open={confirmDelete}
        title={`حذف ${tab === 'personal' ? 'التنبيهات الخاصة' : 'التنبيهات العامة'}؟`}
        body="سيتم حذف التنبيهات في هذا التبويب ولا يمكن التراجع عن هذه العملية."
        confirmLabel="حذف"
        tone="danger"
        busy={busy}
        onConfirm={() => void deleteAll()}
        onCancel={() => setConfirmDelete(false)}
      />

      {toast && <Toast message={toast} onDismiss={() => setToast(null)} />}
    </>
  );
}
